import React, { useState } from 'react'
import { useNavigate, Link } from 'react-router-dom'

function Signup() {
  const navigate = useNavigate()
  const [formData, setFormData] = useState({ name: '', email: '', password: '', confirmPassword: '' })
  const [error, setError] = useState('')

  const handleChange = (e) => {
    const { name, value } = e.target
    setFormData({ ...formData, [name]: value })
  }

  const handleSubmit = (e) => {
    e.preventDefault()
    if (!formData.name || !formData.email || !formData.password || !formData.confirmPassword) {
      setError('Please fill in all fields.')
      return
    }
    if (formData.password !== formData.confirmPassword) {
      setError('Passwords do not match.')
      return
    }
    setError('')
    navigate('/Login')
  }

  return (
    <div style={{ backgroundColor: '#81A6C6', minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
      <div className="card p-4" style={{ width: '400px', backgroundColor: '#F3E3D0', borderRadius: '12px', border: 'none' }}>
        <h2 className="text-center mb-4" style={{ color: '#81A6C6', fontWeight: 'bold' }}>Sign Up</h2>

        {error && <div className="alert alert-danger">{error}</div>}

        <form onSubmit={handleSubmit}>
          <div className="mb-3">
            <label style={{ color: '#81A6C6', fontWeight: 'bold' }}>Full Name</label>
            <input
              type="text"
              name="name"
              className="form-control"
              placeholder="Enter your full name"
              value={formData.name}
              onChange={handleChange}
              style={{ borderRadius: '8px' }}
            />
          </div>

          <div className="mb-3">
            <label style={{ color: '#81A6C6', fontWeight: 'bold' }}>Email address</label>
            <input
              type="email"
              name="email"
              className="form-control"
              placeholder="Enter your email"
              value={formData.email}
              onChange={handleChange}
              style={{ borderRadius: '8px' }}
            />
          </div>

          <div className="mb-3">
            <label style={{ color: '#81A6C6', fontWeight: 'bold' }}>Password</label>
            <input
              type="password"
              name="password"
              className="form-control"
              placeholder="Enter your password"
              value={formData.password}
              onChange={handleChange}
              style={{ borderRadius: '8px' }}
            />
          </div>

          <div className="mb-3">
            <label style={{ color: '#81A6C6', fontWeight: 'bold' }}>Confirm Password</label>
            <input
              type="password"
              name="confirmPassword"
              className="form-control"
              placeholder="Confirm your password"
              value={formData.confirmPassword}
              onChange={handleChange}
              style={{ borderRadius: '8px' }}
            />
          </div>

          <button
            type="submit"
            className="btn w-100"
            style={{ backgroundColor: '#81A6C6', color: '#ffffff', borderRadius: '8px', fontWeight: 'bold' }}
          >
            Sign Up
          </button>

          <p className="text-center mt-3" style={{ color: '#81A6C6' }}>
            Already have an account? <Link to="/Login" style={{ color: '#81A6C6', fontWeight: 'bold' }}>Login</Link>
          </p>
        </form>
      </div>
    </div>
  )
}

export default Signup
